func TestRevenueReport(t *testing.T) {
	st := store.New()
	ny, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Fatal(err)
	}
	// New York starts daylight saving time on 2026-03-08 at 02:00, so March 8 is 23 hours long there.
	at := func(d, h, min int) time.Time { return time.Date(2026, 3, d, h, min, 0, 0, ny) }
	o, _ := st.CreateOrg("A", store.OrgTeam, "America/New_York", 0, at(1, 0, 0))
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", at(1, 0, 0))
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, at(1, 0, 0))
	pay := func(amount int64, cur money.Currency, status store.PaymentStatus, at time.Time) {
		if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: amount, Currency: cur, Status: status}, at); err != nil {
			t.Fatal(err)
		}
	}
	pay(1000, money.USD, store.PaymentSucceeded, at(7, 23, 30)) // Sat 23:30 EST, which is Mar 8 in UTC
	pay(500, money.USD, store.PaymentSucceeded, at(8, 23, 30))  // Sun 23:30 EDT, the 23-hour day's last hour
	pay(200, money.USD, store.PaymentSucceeded, at(9, 0, 30))   // Mon 00:30 EDT
	pay(50, money.USD, store.PaymentSucceeded, at(3, 12, 0))    // before from
	pay(300, money.USD, store.PaymentSucceeded, at(15, 12, 0))
	pay(70, money.EUR, store.PaymentSucceeded, at(15, 12, 0))
	pay(999, money.USD, store.PaymentFailed, at(17, 12, 0))
	pay(900, money.USD, store.PaymentSucceeded, at(18, 12, 0)) // after to

	daily, err := Revenue(st, o.ID, "2026-03-07", "2026-03-08")
	if err != nil {
		t.Fatal(err)
	}
	wantDaily := []DayRevenue{
		{Date: "2026-03-07", Currency: money.USD, Amount: 1000, Payments: 1},
		{Date: "2026-03-08", Currency: money.USD, Amount: 500, Payments: 1},
	}
	if !reflect.DeepEqual(daily, wantDaily) {
		t.Fatalf("Revenue in the time zone = %+v, want %+v", daily, wantDaily)
	}

	check := func(from, to, group string, want []Bucket) {
		t.Helper()
		rep, err := RevenueReport(st, o.ID, from, to, group)
		if err != nil {
			t.Fatal(err)
		}
		if rep.TimeZone != "America/New_York" {
			t.Errorf("time_zone = %q", rep.TimeZone)
		}
		if !reflect.DeepEqual(rep.Buckets, want) {
			t.Errorf("%s to %s by %q: buckets = %+v, want %+v", from, to, group, rep.Buckets, want)
		}
	}
	check("2026-03-07", "2026-03-09", "", []Bucket{
		{Start: "2026-03-07", Amounts: map[money.Currency]int64{money.USD: 1000}, Payments: 1},
		{Start: "2026-03-08", Amounts: map[money.Currency]int64{money.USD: 500}, Payments: 1},
		{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 200}, Payments: 1},
	})
	// The week of March 2 is named by its Monday, even though from is later; the failed and later payments are left out.
	check("2026-03-04", "2026-03-17", "week", []Bucket{
		{Start: "2026-03-02", Amounts: map[money.Currency]int64{money.USD: 1500}, Payments: 2},
		{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 500, money.EUR: 70}, Payments: 3},
		{Start: "2026-03-16", Amounts: map[money.Currency]int64{}, Payments: 0},
	})
	check("2026-02-15", "2026-04-02", "month", []Bucket{
		{Start: "2026-02-01", Amounts: map[money.Currency]int64{}, Payments: 0},
		{Start: "2026-03-01", Amounts: map[money.Currency]int64{money.USD: 2050, money.EUR: 70}, Payments: 6},
		{Start: "2026-04-01", Amounts: map[money.Currency]int64{}, Payments: 0},
	})
	if rep, _ := RevenueReport(st, o.ID, "2026-03-07", "2026-03-07", ""); rep.Group != "day" {
		t.Errorf("default group = %q", rep.Group)
	}
	if _, err := RevenueReport(st, o.ID, "2026-03-01", "2026-03-05", "quarter"); !errors.Is(err, ErrInvalidGroup) {
		t.Errorf("group quarter: %v", err)
	}
}

